// Cantrip Realms' first maps (realms/docs/interfaces.md, "Maps"): Benalish Meadow, generated by the overworld's own
// meadow() (realms/web/src/map.ts) so the server walks the ground the overworld draws, and New Argive, a small town
// square to hold the hub's inn, spell table, armorer and vendors. Samples for the realm server (tech.md M5) until the
// map editor makes the real ones (M6).
//
//     node --experimental-transform-types tools/realms/sample-maps.mjs
//
// Writes realms/content/dominaria/maps/benalish-meadow.json and new-argive.json.

import { register } from "node:module";
import { writeFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

// The overworld imports "./hex" with no extension, as its bundler allows; Node needs one.
register(
  "data:text/javascript," +
    encodeURIComponent(`
      export async function resolve(specifier, context, next) {
        if (specifier.startsWith(".") && !/[.][a-z]+$/.test(specifier.slice(2))) {
          return next(specifier + ".ts", context);
        }
        return next(specifier, context);
      }`),
  import.meta.url,
);

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..", "..");
const { meadow } = await import(pathToFileURL(path.join(root, "realms/web/src/map.ts")).href);
const { spiral, hex, distance } = await import(pathToFileURL(path.join(root, "realms/web/src/hex.ts")).href);

function write(name, map) {
  const file = path.join(root, "realms/content/dominaria/maps", `${name}.json`);
  // Every tile and every other list's entries a line each, so a diff of a map reads.
  const lines = Object.entries(map).map(([key, value]) => {
    const shown = Array.isArray(value) && value.length > 0
      ? "[\n" + value.map((item) => "    " + JSON.stringify(item)).join(",\n") + "\n  ]"
      : JSON.stringify(value);
    return `  ${JSON.stringify(key)}: ${shown}`;
  });
  writeFileSync(file, "{\n" + lines.join(",\n") + "\n}\n");
}

// Benalish Meadow, exactly as the overworld generates it, with the content a map holds beside its ground.
{
  const generated = meadow();
  const tiles = [...generated.all].map((t) => [t.hex.q, t.hex.r, t.height, t.terrain, t.blocked ? 1 : 0]);
  const props = [...generated.all].filter((t) => t.prop).map((t) => ({ q: t.hex.q, r: t.hex.r, kind: t.prop }));
  const open = (q, r) => generated.passable(hex(q, r));
  for (const [q, r] of [[7, 3], [-6, 10], [9, -9], [-10, 1], [0, 2], [16, -8]]) {
    if (!open(q, r)) throw new Error(`benalish-meadow: (${q}, ${r}) is blocked`);
  }
  write("benalish-meadow", {
    id: "benalish-meadow",
    name: "Benalish Meadow",
    kind: "wilderness",
    region: "W",
    radius: 16,
    tiles,
    props,
    exits: [{ q: 16, r: -8, to: "world" }],
    spawns: [
      { id: "s1", q: 7, r: 3, mobs: ["phyrexian-scout", "benalish-deserter", "kjeldoran-raider"], radius: 4, respawnSeconds: 600 },
      { id: "s2", q: -6, r: 10, mobs: ["llanowar-elves-pack"], radius: 3, respawnSeconds: 600 },
      { id: "s3", q: 9, r: -9, mobs: ["shivan-raider", "tolarian-apprentice", "urborg-ghoul"], radius: 4, respawnSeconds: 900 },
    ],
    chests: [{ id: "c1", q: -10, r: 1, gold: [50, 200], respawnSeconds: 86400 }],
    npcs: [{ id: "inn", q: 0, r: 2, kind: "inn" }],
    inn: { q: 0, r: 0 },
  });
}

// New Argive: a paved square, radius 8, its buildings standing on the edge of it.
{
  const radius = 8;
  const npcs = [
    { id: "inn", q: 0, r: -5, kind: "inn" },
    { id: "spell-table", q: 3, r: -3, kind: "spell-table" },
    { id: "armorer", q: -4, r: 0, kind: "armorer" },
    { id: "goblin-trader", q: 5, r: 0, kind: "vendor", vendor: "argive-goblin-trader" },
    { id: "curio-dealer", q: -3, r: 5, kind: "vendor", vendor: "argive-curio-dealer" },
    { id: "artificer", q: 2, r: 4, kind: "vendor", vendor: "argive-artificer" },
    { id: "white-goods", q: -5, r: 3, kind: "vendor", vendor: "argive-white-goods" },
  ];
  const standing = new Set(npcs.map((n) => `${n.q},${n.r}`));
  const tiles = spiral(hex(0, 0), radius).map((h) => {
    const rim = distance(h, hex(0, 0)) === radius;
    const blocked = standing.has(`${h.q},${h.r}`) || (rim && !(h.q === radius && h.r === -4));
    return [h.q, h.r, rim ? 0.5 : 0.25, rim ? "stone" : distance(h, hex(0, 0)) <= 2 ? "sand" : "stone", blocked ? 1 : 0];
  });
  write("new-argive", {
    id: "new-argive",
    name: "New Argive",
    kind: "town",
    region: "hub",
    radius,
    tiles,
    props: [{ q: 3, r: -3, kind: "spell-table" }],
    exits: [{ q: radius, r: -4, to: "world" }],
    spawns: [],
    chests: [],
    npcs,
    inn: { q: 0, r: -4 },
  });
}
